using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.UI;
using CompassNavigatorPro;
using LWS.TruckTaxi;
namespace LWS.TruckPedestrianPlowing.Editor {
 public static class PlowCabAuthoring {
  public const string Scene=PlowAuthoring.Root+"/Scenes/TruckPedestrianPlowingFirstPerson.unity";
  public static void Validate(){var scene=EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<PlowCabMatch>();if(m==null||!m.cabExperience||m.cabExtras==null||m.cabExtras.needsSettings==null||m.cabExtras.gps.Length!=4||m.views.cabRoots.Length!=4||m.cabExtras.gps.Any(g=>g==null||g.GetComponent<Canvas>()==null||g.GetComponent<Canvas>().renderMode!=RenderMode.WorldSpace)||UnityEngine.Object.FindObjectsByType<PlowCabGpsFit>(FindObjectsInactive.Include).Length!=4)throw new Exception("Cab Plowing references incomplete");foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Missing Cab Plowing script "+t.name);if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Cab Plowing listener count");Debug.Log("PLOW_CAB_SAVED_SCENE_VALIDATED");}
  [MenuItem("Truck Sports/Pedestrian Plowing/Update First Person Variant")]
  public static void Create(){
   var scene=EditorSceneManager.OpenScene(PlowAuthoring.Scene);var prior=UnityEngine.Object.FindAnyObjectByType<PlowMatch>();string data=JsonUtility.ToJson(prior);var owner=prior.gameObject;UnityEngine.Object.DestroyImmediate(prior);var m=owner.AddComponent<PlowCabMatch>();JsonUtility.FromJsonOverwrite(data,m);m.cabExperience=true;m.option=2;foreach(var t in m.trucks)t.session=m;m.menus.match=m;m.views.match=m;m.views.rally.session=m;m.hud.match=m;owner.name="Pedestrian Plowing Cab Chaos Authority";
   var extras=owner.AddComponent<PlowCabExtras>();extras.match=m;m.cabExtras=extras;string settingsPath=PlowAuthoring.Root+"/Configuration/Cab Driver Needs.asset";extras.needsSettings=AssetDatabase.LoadAssetAtPath<TruckTaxiEnvironmentSettings>(settingsPath);if(extras.needsSettings==null){extras.needsSettings=ScriptableObject.CreateInstance<TruckTaxiEnvironmentSettings>();extras.needsSettings.startingBladder=.55f;extras.needsSettings.bladderCycleGameHours=new Vector2(.1f,.16f);AssetDatabase.CreateAsset(extras.needsSettings,settingsPath);}
   extras.gps=new CompassPro[4];extras.gpsDestinations=new Transform[4];extras.jugVisuals=new Transform[4];var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LWS/TruckTaxi/Prefabs/TruckTaxi_InterstateTractor.prefab");var driver=source.GetComponentsInChildren<Camera>(true).First(c=>c.name=="Vehicle Camera Driver");Vector3 driverPosition=source.transform.InverseTransformPoint(driver.transform.position);
   for(int i=0;i<4;i++){var camera=m.views.rally.views[i].view;var cab=m.views.cabRoots[i];
    var compassRoot=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Plugins/Kronnect/CompassNavigatorPro/Resources/CNPro/Prefabs/CompassNavigatorPro.prefab"));compassRoot.name="Taxi dashboard GPS · participant view "+i;compassRoot.transform.SetParent(cab,false);var compass=compassRoot.GetComponent<CompassPro>();if(compass==null)compass=compassRoot.GetComponentInChildren<CompassPro>(true);extras.gps[i]=compass;
    var canvas=compass.GetComponent<Canvas>();canvas.renderMode=RenderMode.WorldSpace;canvas.worldCamera=camera;var scaler=canvas.GetComponent<CanvasScaler>();if(scaler!=null)scaler.enabled=false;
    Vector3 point=new Vector3(-.10599f,.71074f,.38486f),normal=new Vector3(-.365503f,.168422f,-.915446f);var rect=compass.transform as RectTransform;var interior=cab.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Taxi cockpit · interior");rect.SetParent(interior,false);rect.localPosition=point+normal.normalized*.012f;rect.localRotation=Quaternion.LookRotation(-normal,Vector3.up);rect.localScale=Vector3.one*.00023f;rect.sizeDelta=new Vector2(640,340);
    compass.compassGroup=20+i;compass.cameraMain=camera;compass.follow=m.trucks[i].transform;compass.showCompassBar=false;compass.showMiniMap=true;compass.miniMapPositionAndSize=MiniMapPositionAndScaleMode.UserDefined;compass.miniMapOrientation=MiniMapOrientation.Follow;compass.miniMapStyle=MiniMapStyle.SolidBox;compass.miniMapContents=MiniMapContents.TopDownWorldView;compass.miniMapResolution=MiniMapResolution._256;compass.miniMapCameraSnapshotFrequency=MiniMapCameraSnapshotFrequency.TimeInterval;compass.miniMapSnapshotInterval=.2f;compass.miniMapLayerMask=5;compass.miniMapCaptureSize=95;compass.miniMapCameraHeightVSFollow=120;compass.miniMapCameraDepth=180;compass.miniMapShowMaximizeButton=false;compass.miniMapShowZoomInOutButtons=false;compass.miniMapShowPlayerIcon=true;compass.routeShowOnMiniMap=true;compass.routeShowInWorld=false;compass.routeShowOnCompassBar=false;compass.routeColor=new Color(.1f,1,.65f);compass.routeWidth=3;
    foreach(var r in compass.GetComponentsInChildren<RectTransform>(true))if(r.name=="MiniMap Root"||r.name=="MiniMap"||r.name=="MiniMapMask"){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;}
    var fit=compass.gameObject.AddComponent<PlowCabGpsFit>();fit.screen=rect;fit.mapRects=compass.GetComponentsInChildren<RectTransform>(true).Where(r=>r.name=="MiniMap Root"||r.name=="MiniMap"||r.name=="MiniMapMask").ToArray();fit.Apply();foreach(var child in compassRoot.GetComponentsInChildren<Transform>(true))child.gameObject.layer=26+i;
    extras.gpsDestinations[i]=new GameObject("GPS positive target view "+i).transform;
    var jug=new GameObject("Driver piss jug · participant "+i).transform;jug.SetParent(cab,false);jug.localPosition=new Vector3(.25f,-.28f,.24f);jug.localScale=Vector3.one*.1f;extras.jugVisuals[i]=jug;
    var material=AssetDatabase.LoadAssetAtPath<Material>(PlowAuthoring.Root+"/Materials/Parade gold.mat");var body=GameObject.CreatePrimitive(PrimitiveType.Cylinder);body.name="Taxi-style jug container";UnityEngine.Object.DestroyImmediate(body.GetComponent<Collider>());body.transform.SetParent(jug,false);body.transform.localScale=new Vector3(.9f,.75f,.9f);body.GetComponent<Renderer>().sharedMaterial=material;
    var cap=GameObject.CreatePrimitive(PrimitiveType.Cylinder);UnityEngine.Object.DestroyImmediate(cap.GetComponent<Collider>());cap.name="Screw cap";cap.transform.SetParent(jug,false);cap.transform.localPosition=new Vector3(0,.85f,0);cap.transform.localScale=new Vector3(.4f,.12f,.4f);cap.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(PlowAuthoring.Root+"/Materials/Stage graphite.mat");
    foreach(var child in jug.GetComponentsInChildren<Transform>())child.gameObject.layer=26+i;
   }
   var option=m.menus.optionText.GetComponentInParent<LWS.TruckSports.SportsMenuAction>();if(option!=null)option.action="cabinfo";m.menus.pages[4].transform.Find("Rules and controls").GetComponent<TMPro.TMP_Text>().text=m.Help;
   EditorSceneManager.SaveScene(scene,Scene);AssetDatabase.SaveAssets();Debug.Log("PLOW_CAB_AUTHORED canonical Taxi interior, CNP GPS and shared Taxi jug state");PlowPolishAuthoring.Install();
  }
 }
}
